import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BqPkuuVc.js";const r="/assets/download-card.C2Lhhf2x.png",s="/assets/docs-run-core-download-panel-listening.DMA5TLPt.png",i="/assets/docs-run-core-download-not-started.BPlIOBH5.png",d="/assets/download-card-ok.Ca-DfQ_z.png",h="/assets/docs-run-core-download-panel-mp1.DOnGxeMZ.png",l="/assets/docs-run-core-download-panel-dnf.ByEEhkLR.png",c="/assets/docs-run-core-download-panel-overtime.CTl_qa3u.png",g="/assets/docs-run-core-download-panel-duplicate.DjVeJg95.png",p="/assets/docs-run-core-download-panel-checkstart.CxJthq46.png",u="/assets/docs-run-core-download-panel-notcompeting.CNn7X7m6.png",m="/assets/docs-run-core-download-panel-unknown.Coe4VChS.png",w="/assets/docs-run-core-download-panel-sharedcourse-registry.Bl4qb0lO.png",f="/assets/docs-run-core-download-panel-sharedcourse-chosen.DLNQzrbn.png",b="/assets/docs-run-core-download-panel-reused.CVFljOv5.png",y="/assets/docs-run-core-download-panel-nostart.D2YQp-wp.png",v="/assets/docs-run-core-download-panel-mpsharedcourse.BcpYa2i5.png",k="/assets/docs-run-core-download-page-mp.CElyqnhI.png",T="/assets/docs-run-core-download-detail-dialog.CkvL3dIa.png",C="/assets/docs-run-core-download-filter-menu.Bs0L9BVl.png",S="/assets/download-issue-punch-strip.DbiYdQmP.png",x="/assets/download-card-incomplete-radio-read.DZrinDW5.png",I="/assets/competitors-edit-manual-download.b5v_2V0d.png",A="/assets/docs-run-core-download-import-backup.B4aovNBD.png",R=JSON.parse('{"title":"Downloading cards","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/card-download.md","filePath":"user/running-the-event/card-download.md"}'),q={name:"user/running-the-event/card-download.md"};function M(_,e,P,D,O,N){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="downloading-cards" tabindex="-1">Downloading cards <a class="header-anchor" href="#downloading-cards" aria-label="Permalink to &quot;Downloading cards&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators at the finish / download station.</p><p>Downloading cards is the core during-event action: a competitor finishes, inserts their card in the reader, and Manager turns the punches into a result. This page covers connecting the reader, the download, what each result means, and the one-click fixes available right after a download.</p><blockquote><p><strong>Note:</strong> This page is about reading competitors&#39; cards at the finish. To recover punches from a <em>control unit&#39;s</em> backup memory, see <a href="./station-memory">Station memory</a>; for radio punches arriving from the field, see <a href="./radio-punches">Radio punches</a>.</p></blockquote><h2 id="before-you-start-browser-and-connection" tabindex="-1">Before you start: browser and connection <a class="header-anchor" href="#before-you-start-browser-and-connection" aria-label="Permalink to &quot;Before you start: browser and connection&quot;">​</a></h2><p>Reading a card reader in the browser uses the <strong>Web Serial API</strong>, which has two requirements:</p><ul><li><strong>Chrome or Edge</strong> (version 89+), <strong>or Firefox</strong> (version 151+), on a desktop or laptop. Safari, older Firefox and phone/tablet browsers don&#39;t support Web Serial and won&#39;t show the reader controls.</li><li><strong>A secure connection.</strong> On the <strong>computer running the server</strong> this is free — open Manager at <code>http://localhost:5154/manager</code> and you&#39;re done. On a <strong>separate download laptop</strong> you must turn on HTTPS and trust meshO&#39;s certificate once. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a> for the full setup; the <strong>Card downloads</strong> page will tell you (<strong>Needs a secure connection</strong>) if it&#39;s needed and not yet in place.</li></ul><blockquote><p><strong>On a managed Firefox, check it&#39;s not switched off.</strong> Firefox added Web Serial in version 151, but it&#39;s disabled by default under Firefox Enterprise Policies — so a laptop supplied by a workplace or school may show no reader controls even on 151+. Either use Chrome or Edge on that machine, or have whoever manages it allow Web Serial. Firefox also asks permission the first time you pick a port, with its own confirmation step on top of the usual device chooser.</p></blockquote><blockquote><p><strong>On a separate laptop, reach the server by its IP.</strong> Download laptops usually run Chrome, and Chrome frequently can&#39;t resolve the server&#39;s computer name, so the name-based link may simply fail to load with <code>DNS_PROBE_FINISHED_NXDOMAIN</code>. Use the link tagged <strong>IP</strong> in <strong>Settings → Server → Access links</strong>. See <a href="./../reference/server-addresses">Reaching the server: name or IP</a>. (Firefox looks names up through the operating system, so the name link is more likely to work there — but the IP link works in every browser, and it&#39;s the one to reach for if anything is misbehaving.)</p></blockquote><p>You&#39;ll also need a <strong>SportIdent USB reader station</strong> — a BSM7-USB or BSM8-USB (the <em>mini Reader</em>) — plugged into the computer.</p><blockquote><p><strong>On a Mac, install the reader driver first.</strong> macOS doesn&#39;t recognise SportIdent&#39;s USB stations out of the box, so no serial port is created and the browser&#39;s device chooser comes up empty. Install the Silicon Labs CP210x driver once per Mac — see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>. Windows and Linux don&#39;t need this.</p></blockquote><blockquote><p><strong>Note — EMIT events:</strong> If your event uses EMIT cards rather than SportIdent, the same <strong>Card downloads</strong> page handles them. See <a href="#emit-readers">EMIT readers</a> for the differences.</p></blockquote><h2 id="connecting-the-reader" tabindex="-1">Connecting the reader <a class="header-anchor" href="#connecting-the-reader" aria-label="Permalink to &quot;Connecting the reader&quot;">​</a></h2><p>Open <strong>Card downloads</strong> from the event menu&#39;s <strong>Race</strong> mode. The page can be opened before the start: a notice at the top says <em>The event hasn&#39;t started</em>, and you can connect the reader and check where splits will print, but cards are read only once the event is live.</p><p><img src="'+r+'" alt="The Card downloads page: the SportIdent panel on the left inviting you to connect a reader, the splits and labels print route below it, and the Downloads list on the right with four reads"></p><p>Then:</p><ol><li>The panel on the left, headed <strong>SportIdent</strong>, says <em>Connect a SportIdent reader to download cards.</em> Plug the reader into a USB port and click <strong>Select device</strong>.</li><li>The browser shows a system dialog listing serial devices — pick the reader and confirm. (On a Mac, if the reader isn&#39;t in that list, you&#39;re missing the driver — see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>.)</li><li>The status chip turns green and reads <strong>Listening</strong>. The panel now prompts <strong>Insert SportIdent card</strong>.</li></ol><p><img src="'+s+'" alt="The SportIdent panel with a reader connected: a green Listening chip with a cross to disconnect it, and the prompt Insert SportIdent card"></p><p>You only pick the device once per browser: after a refresh or a replug, <strong>Select device</strong> reconnects the reader you used before without showing the device chooser. To use a different reader, disconnect first (the <strong>✕</strong> below), then click <strong>Select device</strong>. The green <strong>Listening</strong> chip is your &quot;ready to read&quot; signal — if it&#39;s amber (<strong>Connected</strong>) the reader is attached but not yet listening. The <strong>✕</strong> on the chip disconnects it. Once connected, the reader keeps working as you move around Manager — but <strong>don&#39;t refresh the browser window</strong>, or you&#39;ll have to reconnect (see <a href="#downloads-appear-anywhere">Downloads appear anywhere</a>).</p><p><strong>One reader serves the whole of Manager.</strong> You can connect it here, on the dashboard&#39;s <strong>Download card</strong> tile, on the <strong>SportIdent station</strong> page, on <strong>Station configuration</strong>, or from <strong>Settings → Hire card registry</strong> — wherever you connect it, it&#39;s the same reader, and it downloads cards. Disconnecting it anywhere disconnects it everywhere. See <a href="./station-memory#what-you-need">Station memory</a> for how card downloads pause while a station&#39;s memory is read.</p><p><img src="'+i+'" alt="The Card downloads page of an event still in setup: &quot;The event hasn&#39;t started — You can connect the reader and check the print route now. Cards can be read once the event starts.&quot;"></p><blockquote><p><strong>Tip:</strong> Below the reader panel, a strip says where a card read on this computer prints its splits, and whether that printer can print now. Check it before the first runner arrives. See <a href="./splits-printing">Printing splits</a>.</p></blockquote><h2 id="reading-a-card-—-the-normal-flow" tabindex="-1">Reading a card — the normal flow <a class="header-anchor" href="#reading-a-card-—-the-normal-flow" aria-label="Permalink to &quot;Reading a card — the normal flow&quot;">​</a></h2><p>With the reader listening, ask the user to insert their card:</p><ol><li>A progress bar appears, showing the card number and type while it reads.</li><li>A <strong>result banner</strong> replaces it with the outcome — for a clean run, a green <strong>OK</strong> banner with the competitor&#39;s name, class, course, race time, and current place in their class. If the runner is behind the class leader, the gap follows the time in brackets — <code>Place 3 of 34 | Time 47:23 [+1:36]</code> — when the banner is wide enough to fit it on the same line. On a narrow banner, such as the dashboard tile in a small window, the gap is left out and the line stays the same.</li></ol><p><img src="'+d+'" alt="The Card downloads page after a clean read: a green OK banner for Alex Johnson, M21E Long Red, Place 3 of 34, Time 47:23, 1:36 behind"></p><p>That&#39;s the whole loop, several seconds per card.</p><p><strong>Click the banner</strong> (the arrow in its corner says it can be clicked) to open that competitor&#39;s <strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog on its <strong>Result</strong> tab.</p><h3 id="where-the-download-shows-up" tabindex="-1">Where the download shows up <a class="header-anchor" href="#where-the-download-shows-up" aria-label="Permalink to &quot;Where the download shows up&quot;">​</a></h3><p>What you see depends on which screen you&#39;re on when a card downloads:</p><ul><li><strong>On the Card downloads page</strong> — the reading progress and the result appear in the panel on the left, and every read is added to the <a href="#the-download-history-table">history table</a> on the right.</li><li><strong>On the dashboard</strong> — the <strong>Download card</strong> tile changes state as the card reads and shows the result in place, so you can leave the dashboard up and still watch downloads land.</li><li><strong>On any other screen</strong> — the result pops up in a small panel at the <strong>bottom-right</strong> of the window once the card has finished downloading. Routine results fade after five seconds (hover over the panel to hold it); one that needs attention — an <strong>Unknown card</strong> or a <strong>Card reused</strong> — stays until you handle or close it, and so does the panel while any card read here is still waiting for an owner.</li></ul><p>It&#39;s the same result banner each way, with the same one-click fixes (below) when a download needs them.</p><h2 id="what-the-result-banner-tells-you" tabindex="-1">What the result banner tells you <a class="header-anchor" href="#what-the-result-banner-tells-you" aria-label="Permalink to &quot;What the result banner tells you&quot;">​</a></h2><p>The banner colour and label depend on what Manager made of the punches:</p><table tabindex="0"><thead><tr><th>Banner</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>Green <strong>OK</strong></td><td>A valid result — name, class, course, race time, and place are shown, plus the gap to the class leader if it fits (and the points, on a score course)</td><td>Nothing</td></tr><tr><td>Green <strong>OK</strong> — <em>No start punch</em></td><td>Nothing recorded when they started, so they were timed from their check punch, or from midnight</td><td>Nothing at the desk — see below</td></tr><tr><td><strong>Missing punch</strong></td><td>One or more required controls weren&#39;t punched; the missing control codes are listed</td><td>If it&#39;s a class/course mix-up, use the <a href="#fast-fixes-right-after-a-download">fast fixes</a></td></tr><tr><td><strong>Did not finish</strong></td><td>Did not finish</td><td>Correct if they retired; otherwise investigate later</td></tr><tr><td><strong>Overtime</strong></td><td>They got round, but over the class&#39;s time limit</td><td>Nothing at the desk</td></tr><tr><td>Red <strong>Unknown card</strong></td><td>The card number isn&#39;t held by any competitor in the event</td><td>Assign it to a competitor, or add one — see <a href="#fast-fixes-right-after-a-download">fast fixes</a></td></tr><tr><td><strong>Card reused</strong> — <em>Last used by name</em></td><td>The card has already been round, so this is another run on it, by its owner or by somebody who borrowed it</td><td>Duplicate the owner for this run, or give the card to whoever ran — see <a href="#fast-fixes-right-after-a-download">fast fixes</a></td></tr><tr><td><strong>Duplicate download</strong></td><td>This card has already been downloaded for this competitor, and this read adds nothing to it</td><td>Normal if you re-read the same card — the existing result stands</td></tr><tr><td><strong>Not competing</strong> — <em>No course or class assigned</em></td><td>The card matches a competitor who has no class assigned</td><td>Assign a class and re-check</td></tr><tr><td><strong>Not competing</strong> — <em>No result — class … has no course</em></td><td>The competitor&#39;s class has no course to check the card against, so the run can&#39;t be scored</td><td>Give the class a course, or change their class</td></tr><tr><td><strong>Not competing</strong> — <em>No start time</em></td><td>They completed the course, but nothing says when they started, and the event doesn&#39;t time a run like that from the check punch or midnight</td><td>Give them a start time — see below</td></tr><tr><td><strong>Error</strong></td><td>Something went wrong processing the download</td><td>Re-read the card; if it persists, see <a href="./../reference/troubleshooting">Troubleshooting</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Missing punch</th><th>Did not finish</th><th>Overtime</th></tr></thead><tbody><tr><td><img src="'+h+'" alt="Missing punch banner: Control 102 is missing"></td><td><img src="'+l+'" alt="Did not finish banner for Alex Johnson"></td><td><img src="'+c+'" alt="Overtime banner with a time of 92:15"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Duplicate download</th><th>OK, no start punch</th><th>Not competing, no class</th></tr></thead><tbody><tr><td><img src="'+g+'" alt="Duplicate download banner naming Alex Johnson"></td><td><img src="'+p+'" alt="OK banner with a No start punch chip"></td><td><img src="'+u+'" alt="Not competing banner: No course or class assigned, with Assign class and re-check"></td></tr></tbody></table><p>A missing-punch banner names what&#39;s wrong: the missing control codes, <em>Punched 101 instead of 102</em> when a wrong control was punched, or <em>No finish punch</em>.</p><p>For the rules behind OK / MP / DNF and how race time is worked out, see <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><h2 id="fast-fixes-right-after-a-download" tabindex="-1">Fast fixes right after a download <a class="header-anchor" href="#fast-fixes-right-after-a-download" aria-label="Permalink to &quot;Fast fixes right after a download&quot;">​</a></h2><p>When a download needs attention, Manager offers one-click fixes <strong>on the panel, for the most recent card</strong> — the quickest moment to sort it out, while the runner is still at the desk. (Read the next card and the panel moves on; you can still fix any past download from the <a href="#the-download-history-table">history table</a> or its detail dialog.)</p><p><strong>Unknown card.</strong> When the card number matches nobody in the current event:</p><ul><li><p><strong>Class for this run</strong> comes first, because assigning prints the runner&#39;s splits straight away. It starts on the class the card fits, or on the event&#39;s only class. Where several classes run the course — Men Long, Women Long, Boys Long and Girls Long, say — the card can&#39;t tell them apart, so the box starts empty and says <em>Several classes run this course</em>. Assign stays unavailable until a class is chosen. Somebody already entered in a class keeps it, and the box shows it.</p><p>The list opens with <strong>Classes that fit this card</strong> at the top, then <strong>All classes</strong> in the event&#39;s <a href="./../event-setup/classes-and-courses#class-sort-order">class sort order</a>, so a class is always in the same place. Click the box and type to search: the class already shown is selected, so what you type replaces it, and the results are listed once each, in class order. Typing works the same way in every class box on this page and on the dashboard&#39;s download tile.</p></li><li><p>If the number is recognised in the <a href="./../reference/competitor-registry">Competitor Registry</a>, a one-click <strong>Assign to <em>name</em></strong> button appears, with the class once there is one — it assigns the download to that person, adding them to the event first if they aren&#39;t entered yet.</p></li><li><p>Otherwise, <strong>Assign to existing</strong> lets you search for the competitor and assign the card to them. The search includes people from the registry who aren&#39;t in the event yet; picking one of those says <em>Not entered in this event. Assigning will add them.</em></p></li><li><p>Or <strong>Add competitor</strong> opens the add dialog, pre-filled with the card number and the class above, to create someone new on the spot.</p></li></ul><p><img src="'+m+'" alt="The Unknown card banner, with Class for this run, Assign to existing (a search box and Assign), and Add competitor"></p><table tabindex="0"><thead><tr><th>Several classes run the course</th><th>The class chosen</th></tr></thead><tbody><tr><td><img src="'+w+'" alt="The Unknown card banner for a recognised card: Class for this run is empty and says several classes run this course, and Assign to Pat Morgan and Assign are unavailable"></td><td><img src="'+f+'" alt="The same panel with W20 chosen as the Class for this run, and the button now reading Assign to Pat Morgan – W20"></td></tr></tbody></table><p><strong>The runner is entered, but with no card recorded.</strong> This is the usual reason for an unknown card. Use <strong>Assign to existing</strong>, pick their entry and click <strong>Assign</strong>: their card number is recorded and the download is scored, the same as if the card had been on their entry all along. Don&#39;t use <strong>Add competitor</strong>, which would enter them a second time. If you&#39;d rather fix the entry first, set their <strong>Card number</strong> in <a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a> instead: a download waiting for that number is assigned to them by itself.</p><p>At an event with <strong>Quick name entry on download</strong>, a name box appears here instead, so the desk can type the runner&#39;s name straight in — see <a href="./../event-setup/low-key-events#quick-name-entry-on-download">Quick name entry on download</a>.</p><p>At an event with <strong>Add competitor on download of an unknown card</strong>, the add dialog opens by itself for an unknown card, with the cursor in the first name field — see <a href="./../event-setup/low-key-events#add-competitor-on-download-of-an-unknown-card">Add competitor on download of an unknown card</a>.</p><p>This is also how you fix a <strong>wrong card</strong> — e.g. someone ran on the wrong <a href="./hire-items">hire card</a>. Assign the download to the competitor who actually ran it. If that takes the card off somebody else, or moves another card off the person you assigned it to, a note under the banner says so — <em>This card was taken off name, clearing their result</em> — so nothing changes silently.</p><p><strong>Card reused.</strong> The card has already been round and this read is a later run: its owner going round a second course, or a borrowed card. Manager can&#39;t tell which, so it leaves the owner&#39;s result alone and asks you. The panel shows what the owner already finished as, and what this run came out as. Under <strong>Duplicate for another run</strong>, choose the <strong>Class for this run</strong> and press <strong>Duplicate <em>name</em></strong> to enter the owner a second time for this run, keeping their first result. If somebody else ran on the card, use the search <strong>or a different person</strong> below it. A read that came in over the radio has <strong>Another run by <em>name</em></strong> on it, which does the same in one click, and so does the <strong>Assign</strong> dialog behind the tile&#39;s &quot;cards to assign&quot; alert. See <a href="./who-is-still-on-course#more-than-one-run-on-a-card">More than one run on a card</a>.</p><p><img src="'+b+'" alt="The Card reused banner, last used by Alex Johnson: the card&#39;s last use, OK 47:23, and this run, OK 31:08, with Duplicate for another run (a class for this run and a Duplicate Alex Johnson button), or a different person"></p><p><strong>Cards nobody has dealt with yet.</strong> An unknown card&#39;s banner is replaced by the next card read, so Manager keeps count: while any download is waiting for an owner, <em>N cards to assign</em> shows under the reader panel with <strong>Show</strong> beside it, and the dashboard tile shows the same for cards read at that computer. On this page <strong>Show</strong> filters the history table to <strong>Unassigned</strong>; on the dashboard it lists them.</p><p>At a club training or other event where nobody enters beforehand, Manager can enter unknown cards itself and show the result straight away — see <a href="./../event-setup/low-key-events">Low-key events</a>.</p><p><strong>No class (Not competing).</strong> If the card matches a competitor with no class, pick a class under <strong>Assign class and re-check</strong> and Manager re-evaluates against that class&#39;s course.</p><p><strong>Class with no course (Not competing).</strong> The competitor is in a class that has no course — none was ever set, or it was deleted — so there is nothing to check their card against, and they get no result rather than an OK. The banner names the class, and the <strong>Alerts</strong> panel carries one alert per such class. Give the class a course on the <a href="./../event-setup/classes-and-courses">Classes</a> page and every card read in it is scored again; or, if they are simply in the wrong class, pick the right one under <strong>Change class and re-check</strong>. Their splits still print, with <em>No result: class … has no course</em> under the status, so the runner knows it&#39;s the class and not their run.</p><p><strong>No start punch (still OK).</strong> Nothing recorded when they started, so Manager timed them from their check punch, or from midnight when there was none, and placed them on it. The banner says <em>No start punch</em> and offers nothing else. Their splits print marks the start as a stand-in — <em>Start: 09:27:15 (check punch)</em>, or <em>(no start)</em> from midnight — and <a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a>&#39;s Result tab shows the same beside the start time, with an info icon that explains it. If you know the start they really had, add it as a start override on the competitor&#39;s <strong>Overrides</strong> tab.</p><p><strong>No start time (Not competing).</strong> They got round, but there&#39;s no start punch, allocated start or start override, and the event has its <a href="./../reference/status-and-race-time#a-runner-with-no-start-time">no-start-time fallback</a> switched off. Under <strong>Give them a start time</strong>, type the time they started and <strong>Save start time</strong>, or press <strong>Use check punch</strong> to start them at the check punch on their card. Manager records it as a start time override and scores the card again.</p><p><img src="'+y+'" alt="Not competing — No start time, with Give them a start time: a Start time box, Save start time, and Use check punch (09:27:15)"> No splits print for a read with no start time, because the slip would carry no times; once they have one, you can print theirs from the <strong>Prints</strong> tab of the competitor.</p><p><strong>Missing punch (MP).</strong> If the punches don&#39;t fit the assigned course:</p><ul><li>When the same punches <em>do</em> satisfy another class&#39;s course, Manager suggests it — <em>OK for <strong>W21A</strong> [Hard 2]</em> — with a <strong>Change class</strong> button to accept the reassignment in one click. This is the common &quot;started in the wrong class&quot; fix. Where several classes run that course, Manager names the course and leaves the class to you: choose it under <strong>Change class and re-check</strong>.</li><li>In a class whose runners are allotted different variations of a forked course, when the punches fit a different variation of the same course, Manager says so — <em>OK for variation <strong>B</strong> of Course 1 — likely a wrong variation allocation</em> — with <strong>Assign variation B</strong>.</li><li>Otherwise, use <strong>Change class and re-check</strong> to choose a class yourself and re-evaluate.</li></ul><p><img src="'+v+'" alt="A Missing punch banner with the message OK on Course 3, which several classes run. Choose the class below, above Change class and re-check"></p><p><img src="'+k+'" alt="The Card downloads page after a mis-punch: an outlined Missing punch banner with the print countdown and cross at its top left, Controls 34 and 41 missing, and Change class and re-check below"></p><blockquote><p><strong>The MP slip waits while you do this.</strong> Most mis-punches are a wrong-course mix-up, so printing straight away means printing twice. An arc around a small printer icon on the banner counts the window down (20 seconds by default); correct the class and the <em>corrected</em> slip prints at once. Press the <strong>✕</strong> beside it, or open any dialog about that runner, to end the wait with nothing printed. Full detail — including the setting — in <a href="./splits-printing#mis-punches-wait-before-they-print">Mis-punches wait before they print</a>.</p></blockquote><h2 id="the-card-download-detail-dialog" tabindex="-1">The card download detail dialog <a class="header-anchor" href="#the-card-download-detail-dialog" aria-label="Permalink to &quot;The card download detail dialog&quot;">​</a></h2><p>Click any card number (on the panel or in the history table) to open the <strong>Card download</strong> detail dialog. It shows when it was downloaded and the <strong>punch-by-punch breakdown</strong> — every control, code, and split — alongside the class, course, and status. From here you can, for <em>any</em> download (not just the latest):</p><ul><li><strong>Assign</strong> an unassigned card to a competitor (or add a new one), or <strong>Assign to <em>name</em></strong> when the card is known to the registry</li><li><strong>Change class/course</strong> — re-evaluate against a different class or course, and <strong>Re-check</strong></li><li><strong>Unassign</strong> the download from its competitor, which clears their result and leaves the download as <strong>Unassigned</strong> — then assign it to whoever really ran</li><li><strong>Delete</strong> the download entirely, after you confirm. Downloads are deleted one at a time, from here; there is no Delete all. The competitor&#39;s result goes with it; the backup file on disk is kept, and the deletion is recorded in the <a href="./../reference/audit-trail">audit trail</a>.</li></ul><p><img src="'+T+'" alt="The Card download dialog for card 441003: SI Card 9 with its battery voltage, Jordan Lee, class and course M21E, status MP, the punches with their times, and Delete, Unassign, Change class/course and Close"></p><p>The chips beside the card number give the card type and, for a SIAC, its battery voltage.</p><p>Use this dialog when the quick panel actions have already scrolled past, or when you need to see exactly which controls were punched and in what order.</p><h2 id="the-download-history-table" tabindex="-1">The download history table <a class="header-anchor" href="#the-download-history-table" aria-label="Permalink to &quot;The download history table&quot;">​</a></h2><p>The right side of the page lists every card read, newest first: <strong>Download time</strong>, <strong>Card number</strong>, <strong>Competitor</strong>, <strong>Class</strong> and <strong>Status</strong>. Its title is <strong>Card downloads</strong> with the count, shortened to <strong>Downloads</strong> when the window is narrow. Search it with <strong>Competitor / card</strong>. <strong>Filter</strong> opens a menu with a <strong>Class</strong> section and a <strong>Status</strong> section (<strong>OK</strong>, <strong>Unassigned</strong>, <strong>MP</strong>, <strong>DNF</strong>, <strong>Not competing</strong>, <strong>Disqualified</strong>, <strong>Overtime</strong>); the chosen item is marked, the button counts the filters in force, <strong>Clear all</strong> removes them and <strong>Close</strong> shuts the menu. For each row you can:</p><p><img src="'+C+'" alt="The Downloads list with its Filter menu open: a Class section and a Status section, with Clear all and Close"></p><ul><li>Click the <strong>card number</strong> to open the detail dialog</li><li>Click the <strong>competitor name</strong> to open their <strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog — or, for an unassigned card with a provisional (italic) name, click it to add that person and assign in one step</li><li>Change the <strong>class</strong> inline with the dropdown in the Class column</li><li><strong>Print splits</strong> with the printer icon (see below)</li><li>Click the <strong>arrow</strong> at the start of a row whose result isn&#39;t clean to see what went wrong: the missing controls, and the course as a strip of boxes, each control in course order with its split, the missing ones in red</li></ul><p><img src="'+S+'" alt="A mis-punched row expanded: &quot;Controls 100, 101 are missing&quot; over a strip of Start, the four controls and Finish, the two missing ones red"></p><p>The status column shows the competitor&#39;s current status chip, the course, or an orange <strong>Unassigned</strong> chip. A <strong>Manual</strong> chip beside a card number marks a <a href="#manual-downloads">manual download</a>, and <strong>Radio</strong> one <a href="#cards-read-over-the-radio-network">read over the radio network</a>.</p><h2 id="downloads-appear-anywhere" tabindex="-1">Downloads appear anywhere <a class="header-anchor" href="#downloads-appear-anywhere" aria-label="Permalink to &quot;Downloads appear anywhere&quot;">​</a></h2><p>You don&#39;t have to stay on the <strong>Card downloads</strong> page — once the reader is connected, it keeps reading as you move around Manager, and each result shows up in whichever form fits the screen you&#39;re on (<a href="#where-the-download-shows-up">as above</a>).</p><p>The one exception is a <strong>card number box</strong>. In the dashboard&#39;s <strong>Quick competitor actions</strong>, the <a href="./../reference/competitor-registry">Competitor Registry</a> and <strong>Settings → Hire card registry</strong>, click into the card number box and insert a card: its number is filled in, and the card is not downloaded. A small reader icon in the box says when it&#39;s taking a card. Click anywhere else and the next card downloads as usual. <strong>Add competitor</strong> and <strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> work differently: a reader icon beside <strong>Card number</strong> turns this on and off, and it starts off (see <a href="./late-entries#reading-the-card-number-off-the-card">Reading the card number off the card</a>).</p><blockquote><p><strong>Warning — don&#39;t refresh the browser window.</strong> Navigating between Manager&#39;s screens keeps the reader connected, but <strong>reloading the page (or closing the tab) drops the connection</strong> — you&#39;ll have to click <strong>Select device</strong> to carry on, though you won&#39;t have to pick the device again. Cards you&#39;ve already read are safe: they&#39;re stored on the server the moment they download. It&#39;s only the live reader link that has to be re-established.</p></blockquote><h2 id="cards-read-over-the-radio-network" tabindex="-1">Cards read over the radio network <a class="header-anchor" href="#cards-read-over-the-radio-network" aria-label="Permalink to &quot;Cards read over the radio network&quot;">​</a></h2><p>A card read by a radio download station at the finish reaches Manager over the meshO network, with nobody at a desk. The station reads a card again and again while the runner stays near it, and more than one meshO Control can hear it, so one card arrives as many readouts — some with records missing. Manager puts them together and keeps <strong>one download per card</strong>:</p><ul><li><strong>It waits for the whole card.</strong> A card is downloaded as soon as every record on it has arrived, from any of its readouts. If records are still missing, Manager waits until nothing more of the card has been heard for half a minute, then downloads what it has.</li><li><strong>A fuller read replaces a shorter one.</strong> If more of the card arrives later — the runner goes back to the station, or you read the card here at the desk — the fuller read takes the shorter one&#39;s place on the same competitor, and the shorter one is removed. You don&#39;t need to delete anything first. The removal is recorded in the <strong>Audit trail</strong>, and its file stays on disk.</li><li><strong>A read with nothing new is a duplicate</strong>, and isn&#39;t stored at all.</li></ul><p>A card read over the radio shows a <strong>Radio</strong> chip beside its card number in the history table and the detail dialog. If records were still missing when it was downloaded, an <strong>Incomplete</strong> chip sits beside it: the result may be an <strong>MP</strong> or <strong>DNF</strong> the runner never earned. <img src="'+x+'" alt="The Downloads list with two cards read over the radio, each marked Radio, one also Incomplete"></p><p>Read that card here at the desk — the desk read holds everything the radio read did, so it replaces it, and the chip goes with it.</p><p>When a fuller read leaves the result as it was, nothing more is printed — the runner already has (or is about to get) the slip it would print.</p><h2 id="printing-splits" tabindex="-1">Printing splits <a class="header-anchor" href="#printing-splits" aria-label="Permalink to &quot;Printing splits&quot;">​</a></h2><p>The printer icon on each history row prints that competitor&#39;s split times, where this computer&#39;s splits go — the strip at the top of the page says which printer that is, and whether it can print now. To print automatically on every download, turn on <strong>Automatic print splits on download</strong> — globally in <strong>Settings → Printing → Splits print</strong>, or per event under <strong>Edit</strong> event details → <strong>Printing</strong>. See <a href="./splits-printing">Printing splits</a> for the whole picture: what a printout contains, where printers can be, and which computer prints where.</p><h2 id="hire-items" tabindex="-1">Hire items <a class="header-anchor" href="#hire-items" aria-label="Permalink to &quot;Hire items&quot;">​</a></h2><p>If a downloaded card is one of your hire cards — or belongs to a competitor holding a compass, a map board or anything else you lend — Manager prompts you to <strong>collect it all</strong> so none of it walks off. That prompt, and how to manage what you hire out, are covered in <a href="./hire-items">Hire items</a>.</p><h2 id="manual-downloads" tabindex="-1">Manual downloads <a class="header-anchor" href="#manual-downloads" aria-label="Permalink to &quot;Manual downloads&quot;">​</a></h2><p>Sometimes a runner has no card to read. A <strong>manual download</strong> lets you type their run in yourself, and Manager then evaluates it exactly as it would a card it had read — status, race time, splits, placing. Typical reasons:</p><ul><li><strong>A lost card.</strong> The runner finished but the card didn&#39;t come back. Type in their start, finish and controls (from the finish unit, the station backups or the radio punches).</li><li><strong>Two runners went round together on one card.</strong> Copy the download of the card that was read onto the runner who didn&#39;t have one.</li><li><strong>Testing.</strong> Try out a course, a class or a results screen with a made-up run before the event.</li></ul><p>Open the competitor&#39;s <strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog and go to the <strong>Download</strong> tab, which shows the card read on their record, if any. The button at the bottom of the tab is:</p><ul><li><strong>New manual download…</strong> — when the competitor has no download at all.</li><li><strong>Edit manual download…</strong> — when the download on the tab is a manual one.</li></ul><p>A competitor who already has a card read gets neither: a competitor holds one download, and a card read is the record of what their card held. Correct it on the <strong>Overrides</strong> tab instead (see <a href="./resolving-issues">Resolving issues</a>). If the read on their record isn&#39;t theirs at all, unassign or delete it from the <a href="#the-card-download-detail-dialog">card download detail dialog</a> first.</p><p>The form has a <strong>Start</strong> and a <strong>Finish</strong> time and a list of <strong>Controls</strong>, each with its code and time. Times are hours, minutes and seconds (type the digits — <code>103015</code> is 10:30:15); fractions of a second aren&#39;t used. Leave the start or finish empty if the run didn&#39;t have one, just as a card wouldn&#39;t. When you&#39;re making a new one, <strong>Copy from a download</strong> at the top fills the form from any other download in the event — this is how you copy a partner&#39;s card. Copying only reads it: that download isn&#39;t changed and stays with the competitor it belongs to. Editing doesn&#39;t offer a copy. When you&#39;re starting from nothing, <strong>Fill from course</strong> adds a row for each control of the runner&#39;s course, in order, ready for their times.</p><p><img src="'+I+'" alt="New manual download, filled by copying Sam Williams&#39; read: Start 09:47:00, Finish 10:13:50, and four controls with their codes and times, Add control, Cancel and Save"></p><p>Rows can be removed with the bin beside them, and <strong>Add control</strong> adds one. Nothing changes until you click <strong>Save</strong>. Manager then evaluates the run and the competitor&#39;s result updates. <strong>Cancel</strong> leaves everything as it was.</p><p>Things to know:</p><ul><li><strong>A card read is never changed.</strong> Only manual downloads can be edited. In the history table a manual download is marked <strong>Manual</strong> beside its card number.</li><li><strong>Editing replaces the manual download.</strong> The version you replaced is recorded in the competitor&#39;s <strong>Audit trail</strong> tab, and its file stays on disk, so it can turn up in <a href="#import-from-backup">Import from Backup</a>.</li><li><strong>Deleting it.</strong> <strong>Delete</strong> at the bottom of <strong>Edit manual download</strong> removes it, once you confirm. The result it gave goes too — the competitor falls back to what their radio punches say, or to no result — and <strong>New manual download…</strong> is offered again. Like any deleted download it&#39;s recorded in the <strong>Audit trail</strong> and its file stays on disk.</li><li><strong>A manual download belongs to the competitor you made it for.</strong> It&#39;s never matched to anyone by card number, and it never changes the competitor&#39;s card number. Correcting their card number afterwards keeps it.</li><li><strong>Times are whole seconds.</strong> Copying a download that recorded fractions of a second (SIAC beacon punches) drops the fractions, and the form tells you. The check punch isn&#39;t copied.</li><li><strong>Nothing is printed automatically</strong>, because the runner isn&#39;t standing at a download desk. Print from the competitor&#39;s <strong>Prints</strong> tab if you need to.</li><li><strong>Not at the entry desk.</strong> The <a href="./registration-desk">registration desk</a> shows a competitor&#39;s download but doesn&#39;t offer manual downloads.</li></ul><h2 id="import-from-backup" tabindex="-1">Import from Backup <a class="header-anchor" href="#import-from-backup" aria-label="Permalink to &quot;Import from Backup&quot;">​</a></h2><p>Downloads are stored in the event database by the server as they&#39;re read. If downloads were taken on another machine, or you&#39;re rebuilding an event, <strong>Actions → Import from backup</strong> (top right of the history table) scans the disk for card-download files Manager hasn&#39;t loaded yet (or were deleted) and lets you pick which to bring in. If everything on disk is already loaded, it tells you so.</p><p><img src="'+A+'" alt="Import card downloads from backup: &quot;Found 4 card downloads on disk not loaded in memory&quot;, a Select all box, a tick beside each card number, and Cancel and Import"></p><h2 id="when-a-card-won-t-read" tabindex="-1">When a card won&#39;t read <a class="header-anchor" href="#when-a-card-won-t-read" aria-label="Permalink to &quot;When a card won&#39;t read&quot;">​</a></h2><p>If a card fails to read, the panel shows a read error rather than a result.</p><ul><li>Ask the runner to remove the card and try again.</li><li>Check the reader is still <strong>Listening</strong> (green chip) — reconnect with <strong>Select device</strong> if the chip has dropped.</li><li>Try a different USB port or cable if reads keep failing.</li></ul><p>A card that won&#39;t read in one reader will usually read in another; if a specific card fails everywhere, it may be faulty. Its run can still be entered from the finish unit&#39;s <a href="./station-memory">station memory</a> or the radio punches as a <a href="#manual-downloads">manual download</a>.</p><p>If the reader stops taking cards although it still shows as connected, Manager raises an alert — <em>The card reader has stopped reading cards, although it is still connected</em> — and another when it recovers. Disconnect it and connect it again. Other messages you may meet when connecting:</p><ul><li><strong>The reader is no longer attached to this computer</strong> — it was unplugged. Plug it back in, then <strong>Select device</strong> again.</li><li><strong>Failed to open port. The device may be in use by another application</strong> — close other software that uses the reader, then try again.</li><li><strong>Port is already open or in an invalid state</strong> — refresh the browser window and select the device again.</li></ul><h2 id="emit-readers" tabindex="-1">EMIT readers <a class="header-anchor" href="#emit-readers" aria-label="Permalink to &quot;EMIT readers&quot;">​</a></h2><p>If the event&#39;s <strong>Timing card system</strong> is EMIT, the same page reads EMIT cards. The timing card system comes from <strong>Settings → <a href="./../reference/settings#event-defaults">Event defaults</a></strong> for a new event, and can be changed in the event&#39;s details while it&#39;s still in setup.</p><ul><li>The panel is headed <strong>Reader</strong>. After you pick the device, Manager asks <strong>Which reader did you connect?</strong> — <strong>EMIT MTR4</strong> or <strong>EMIT 250</strong> — because the two talk differently.</li><li>The prompt reads <strong>Read card</strong> instead of <strong>Insert SportIdent card</strong>. Everything after a read — the result banner, the fixes, the history table, printing — is the same.</li><li>With an MTR4, <strong>Status</strong> shows the unit&#39;s number, whether its battery is <strong>LOW</strong> or <strong>OK</strong>, and the range of readouts it holds, and <strong>Re-read all</strong> asks it to send every readout in its memory again. A card Manager already has comes back as a duplicate and changes nothing.</li><li>EMIT records times in whole seconds from the moment the card was cleared at the start, and the last control on the card is taken as the finish. Manager turns those into times of day from the competitor&#39;s start time, so enter EMIT runners, with their start times, before their cards are read.</li></ul><p>The browser needs are the same as for SportIdent (Chrome, Edge or Firefox 151+, and a secure connection).</p><h2 id="for-problems-noticed-later" tabindex="-1">For problems noticed later <a class="header-anchor" href="#for-problems-noticed-later" aria-label="Permalink to &quot;For problems noticed later&quot;">​</a></h2><p>The fast fixes above are for the moment of download. For anything you spot after the runner has gone — a result that needs an overridden status, punches to edit, a competitor to re-evaluate — work from the competitor&#39;s record instead. See <a href="./resolving-issues">Resolving issues on the day</a>.</p><h2 id="downloading-a-card-after-you-ve-finished-the-event" tabindex="-1">Downloading a card after you&#39;ve finished the event <a class="header-anchor" href="#downloading-a-card-after-you-ve-finished-the-event" aria-label="Permalink to &quot;Downloading a card after you&#39;ve finished the event&quot;">​</a></h2><p>Downloading is only available while the event is live, but that isn&#39;t a one-way door. If someone walks out of the forest after you&#39;ve clicked <strong>Finish event</strong> — or turns up the next day with an unread card — open the event and choose <strong>Restart event</strong> from the state button at the top right. The event goes live again, you download the card as normal, and you finish the event a second time afterwards.</p><p>The late download gives the same result it would have on the day: the card carries the times of day the competitor punched, not elapsed time, so it doesn&#39;t matter when you read it. See <a href="./dashboard#restarting-an-event-you-ve-already-finished">Restarting an event you&#39;ve already finished</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — the competitor records cards are matched to</li><li><a href="./../event-setup/classes-and-courses">Classes and courses</a> — the classes and courses a download is evaluated against</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — how OK / MP / DNF and race time are decided</li><li><a href="./splits-printing">Printing splits</a> — the slip a download prints, and where the printers go</li><li><a href="./hire-items">Hire items</a> — the collect-on-download prompt and managing what you lend</li><li><a href="./../event-setup/low-key-events">Low-key events</a> — entering unknown cards, and making courses from them, automatically</li></ul>',120)])])}const W=t(q,[["render",M]]);export{R as __pageData,W as default};
